package android.util;public final class Base64 {public static final int DEFAULT=0,NO_PADDING=1,NO_WRAP=2,CRLF=4,URL_SAFE=8;
public static byte[] decode(String s,int flags){return ((flags&URL_SAFE)!=0?java.util.Base64.getUrlDecoder():java.util.Base64.getMimeDecoder()).decode(s);}
public static String encodeToString(byte[] b,int flags){java.util.Base64.Encoder e=(flags&URL_SAFE)!=0?java.util.Base64.getUrlEncoder():java.util.Base64.getEncoder();if((flags&NO_PADDING)!=0)e=e.withoutPadding();String s=e.encodeToString(b);if((flags&NO_WRAP)!=0||s.isEmpty())return s;String sep=(flags&CRLF)!=0?"\r\n":"\n";StringBuilder out=new StringBuilder();for(int i=0;i<s.length();i+=76)out.append(s, i,Math.min(i+76,s.length())).append(sep);return out.toString();}}
